# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: every keyboard shortcut of reflex-kernel, named by what it does (Shortcut.FULL_SCREEN).
#          The one place keys are set: the help panel, button tooltips, the cell editor's keymap,
#          the keybindings list (Alt+K) and assets/panes.js / keys.js (via window.SHORTCUTS, see
#          shortcuts_script) all read it.
# ---------------------------------------------------------------------------
from __future__ import annotations

import json
from dataclasses import dataclass
from enum import Enum


@dataclass(frozen=True)
class Binding:
    keys: str
    """As shown and matched: modifiers then the key, joined by "+", eg "Alt+F", "Ctrl+Enter", "Escape"."""
    where: str
    what: str


class Shortcut(Enum):
    # Handled by assets/panes.js (window.SHORTCUTS).
    FULL_SCREEN = Binding("Alt+F", "result, pane", "Full screen: float the result you are in, else fill with your pane")
    CLOSE = Binding("Escape", "floating result, menu, help, debug log, keybindings", "Close it")
    TOGGLE_RESULTS = Binding("Alt+R", "anywhere", "Show or hide the Results pane")
    TOGGLE_PYTHON = Binding("Alt+J", "anywhere", "Show or hide the Python (Jupyter) pane")
    HELP = Binding("Alt+H", "anywhere", "Show or hide this help")
    PALETTE = Binding(
        "Alt+P", "anywhere", "Command palette: run anything by name, eg add a widget (type to filter, arrows, Enter)"
    )
    # Handled by assets/keys.js.
    KEYS = Binding("Alt+K", "anywhere", "Show or hide the keybindings list (type to filter)")
    DEBUG = Binding("Alt+D", "anywhere", "Show or hide the debug log: every request the app made, memory")
    # Handled by the chat box (a form textarea).
    SEND = Binding("Enter", "chat", "Send")
    NEW_LINE = Binding("Shift+Enter", "chat", "New line")
    # Handled by the cell editor's keymap (cell_editor.jsx, given by codemirror_keys).
    RUN_AND_ADVANCE = Binding("Shift+Enter", "cell", "Run and go to the next cell")
    RUN = Binding("Ctrl+Enter", "cell", "Run")
    COMPLETE = Binding("Tab", "cell, table SQL, SmashDb console", "Complete")
    # Handled by inline_edit.jsx, in a cell and the SmashDb console's SQL box.
    INLINE_EDIT = Binding(
        "Alt+A",
        "cell, SmashDb console",
        "Inline chat, knowing the chat so far: ask AI to write or change the code (the selection, else all); Tab accepts, Esc discards",
    )
    INLINE_EDIT_FRESH = Binding(
        "Alt+Shift+A",
        "cell, SmashDb console",
        "Inline chat, fresh: the same, without the chat (faster; sees only the code, variables and tables)",
    )
    # Handled by the SQL box (sql_editor.jsx): a table view's, and a SmashDb console's editor.
    RUN_SQL = Binding(
        "Ctrl+Enter",
        "table SQL, SmashDb console",
        "Run the query (polars SQL; a table's own box queries it as self; a selection runs alone)",
    )
    # A mouse action, listed for the help panel.
    TAB_MENU = Binding("Right-click", "result tab", "Show in Chat, Close, Close Others, Close to the Right, Close All")

    @property
    def keys(self) -> str:
        return self.value.keys

    def hint(self, text: str) -> str:
        """A tooltip with the shortcut, eg "Full screen (Alt+F)"."""
        return f"{text} ({self.keys})"


# What panes.js and keys.js match on keydown.
BROWSER_SHORTCUTS = (
    Shortcut.FULL_SCREEN,
    Shortcut.CLOSE,
    Shortcut.TOGGLE_RESULTS,
    Shortcut.TOGGLE_PYTHON,
    Shortcut.HELP,
    Shortcut.PALETTE,
    Shortcut.KEYS,
    Shortcut.DEBUG,
    # an editor's own keys (inline_edit.jsx): panes.js needs them to run one from the palette
    Shortcut.INLINE_EDIT,
    Shortcut.INLINE_EDIT_FRESH,
)


def shortcuts_script() -> str:
    """JS that sets window.SHORTCUTS for panes.js, eg {"FULL_SCREEN": "Alt+F", "CLOSE": "Escape"}."""
    return f"window.SHORTCUTS = {json.dumps({s.name: s.keys for s in BROWSER_SHORTCUTS})};"


def codemirror_key(shortcut: Shortcut) -> str:
    """CodeMirror's spelling of a binding: "Ctrl+Enter" -> "Mod-Enter" (Cmd on a Mac), "Alt+A" -> "Alt-a",
    "Alt+Shift+A" -> "Alt-Shift-a" (CodeMirror wants the letter in lower case, Shift named apart)."""
    *mods, key = shortcut.keys.split("+")
    return "-".join(["Mod" if mod == "Ctrl" else mod for mod in mods] + [key.lower() if len(key) == 1 else key])


def sql_keys() -> dict[str, str]:
    """The SQL box's keymap, by the prop names sql_editor.jsx reads."""
    return {
        "run": codemirror_key(Shortcut.RUN_SQL),
        "complete": codemirror_key(Shortcut.COMPLETE),
        "inlineEdit": codemirror_key(Shortcut.INLINE_EDIT),
        "inlineEditFresh": codemirror_key(Shortcut.INLINE_EDIT_FRESH),
    }


def codemirror_keys() -> dict[str, str]:
    """The cell editor's keymap, by the prop names cell_editor.jsx reads."""
    return {
        "run": codemirror_key(Shortcut.RUN),
        "runAndAdvance": codemirror_key(Shortcut.RUN_AND_ADVANCE),
        "complete": codemirror_key(Shortcut.COMPLETE),
        "inlineEdit": codemirror_key(Shortcut.INLINE_EDIT),
        "inlineEditFresh": codemirror_key(Shortcut.INLINE_EDIT_FRESH),
    }
